//! Finite caller errors, independent of durable execution failure codes.
const d = @import("root.zig").protocol.Diagnostic;
pub const Entry = struct { cause: anyerror, code: []const u8, category: d.Category, action: d.ActionKind, message: []const u8 };
pub const entries = [_]Entry{
    .{ .cause = error.QueryReadConflict, .code = "query.read_conflict", .category = .conflict, .action = .retry_read, .message = "The resource or policy changed during the bounded read. Retry the read under current rights without replacing any saved command." },
    .{ .cause = error.Conflict, .code = "query.authority_conflict", .category = .conflict, .action = .inspect_status, .message = "The authority rejected this attempt as conflicting. Inspect its native cause and any saved query; this response alone does not identify a changed source or settle earlier work." },
    .{ .cause = error.Rejected, .code = "query.authority_rejected", .category = .conflict, .action = .inspect_status, .message = "The authority rejected this attempt. Inspect its native cause and the exact saved query. This is not a terminal query outcome or permission to replace an uncertain command." },
    .{ .cause = error.InvalidQueryRequest, .code = "query.invalid_command", .category = .binding, .action = .correct_input, .message = "The command encoding or fields are invalid. No command was sent by this attempt. Preserve any earlier saved work while correcting the request." },
    .{ .cause = error.QueryIdentityMismatch, .code = "query.identity_mismatch", .category = .conflict, .action = .inspect_status, .message = "The selected source, saved command, request or result does not match this query scope. Preserve the original identity and inspect its connection and source commitment; do not substitute another query." },
    .{ .cause = error.InvalidQueryIdentity, .code = "query.invalid_identity", .category = .binding, .action = .correct_input, .message = "The query or input identity is invalid for this observation. Use the exact saved identity; native input positions must not exceed the authority position." },
    .{ .cause = error.InvalidQueryCursor, .code = "query.invalid_cursor", .category = .binding, .action = .inspect_status, .message = "The result cursor is malformed or does not match this result reference, ordinal, row count or byte coverage. Retain the original cursor and inspect the exact saved query; a new query cannot repair this continuation." },
    .{ .cause = error.InvalidSqlCursor, .code = "query.invalid_sql_cursor", .category = .binding, .action = .correct_input, .message = "The SQL editor cursor is outside the statement or splits a UTF-8 character. Supply a byte offset at a character boundary within this statement." },
    .{ .cause = error.InvalidPredicateProgram, .code = "query.invalid_predicate_program", .category = .integrity, .action = .contact_operator, .message = "The typed predicate has invalid instruction, literal-storage or stack bounds. Preserve the original plan and correct its construction before submission." },
    .{ .cause = error.IncompleteResult, .code = "query.result_incomplete", .category = .lifecycle, .action = .inspect_status, .message = "The selected query does not have a complete result available. Inspect its exact status; pending, rejected, cancelled and retired outcomes require different handling. Do not submit the SQL again to obtain a result." },
    .{ .cause = error.OutOfMemory, .code = "query.memory_unavailable", .category = .unavailable, .action = .inspect_status, .message = "The caller could not allocate memory for this operation. Preserve any saved command and previously observed outcome; allocation failure does not settle them." },
    .{ .cause = error.InvalidQueryUpload, .code = "query.invalid_upload_evidence", .category = .integrity, .action = .contact_operator, .message = "The retained upload record or publication does not match its expected specification and phase. Preserve the original bundle and namespace; do not overwrite or resume from unverified progress." },
    .{ .cause = error.QueryUploadIdentityConflict, .code = "query.upload_identity_conflict", .category = .conflict, .action = .inspect_status, .message = "This namespace or retained upload part belongs to different exact bundle bytes. Preserve and inspect the original upload. Recompiling SQL or replacing bytes at this identity cannot reconcile it." },
    .{ .cause = error.QueryUploadNotFound, .code = "query.upload_absent", .category = .lifecycle, .action = .inspect_status, .message = "This authorized observation found no upload at the selected query namespace. Check the original identity and admission receipt. Absence does not prove that an uncertain submission was never accepted." },
    .{ .cause = error.QueryRequesterUnavailable, .code = "query.requester_unavailable", .category = .lifecycle, .action = .inspect_scope, .message = "The configured requester process is no longer running. Inspect its lifecycle and retained query records under current authority. This does not establish failure or cancellation of earlier query work." },
    .{ .cause = error.QueryRequesterFailed, .code = "query.requester_failed", .category = .lifecycle, .action = .inspect_status, .message = "The requester process has a recorded process failure. Inspect that process and the exact query before continuing. Process failure is separate from the query result and does not authorize resubmission." },
    .{ .cause = error.QuerySourceUnavailable, .code = "query.source_unavailable", .category = .lifecycle, .action = .inspect_scope, .message = "A required source/request resource is inactive or does not belong to the configured owner. Inspect the original resource and owner identities under current authority; this does not settle previously accepted work." },
    .{ .cause = error.QueryDraftNotFound, .code = "query.draft_absent", .category = .lifecycle, .action = .inspect_status, .message = "The selected draft generation is absent in this authorized observation. Inspect the exact generation and earlier accepted query identities before reviewing another generation." },
    .{ .cause = error.QueryDraftClosed, .code = "query.draft_closed", .category = .lifecycle, .action = .inspect_status, .message = "The selected draft generation is disabled or no longer current. It cannot select new query work. Queries already started by that generation retain their own outcomes." },
    .{ .cause = error.QueryDraftConflict, .code = "query.draft_conflict", .category = .conflict, .action = .inspect_status, .message = "The query source contract or namespace does not match the selected draft generation. Retain the original generation and query identities; inspect their recorded membership and contract before continuing." },
    .{ .cause = error.QueryDraftExhausted, .code = "query.draft_start_limit", .category = .limit, .action = .inspect_status, .message = "The draft generation has used its finite query-start budget. This preparation selected no new query. Inspect its limit and already selected namespaces before explicitly reviewing another generation." },
    .{ .cause = error.ResultUnavailable, .code = "query.result_unavailable", .category = .lifecycle, .action = .inspect_status, .message = "The retained job or result publication no longer matches the expected complete result. Inspect the exact saved query and result reference. Unavailable result data does not prove that computation failed or authorize running the SQL again." },
    .{ .cause = error.InvalidQueryManifest, .code = "query.invalid_result_manifest", .category = .integrity, .action = .contact_operator, .message = "The result manifest has an invalid identity, publication format, source basis or recorded bounds. No verified result can be returned. Preserve its original reference and saved query for inspection." },
    .{ .cause = error.MissingResultSegment, .code = "query.result_segment_missing", .category = .integrity, .action = .contact_operator, .message = "A segment required by the retained result manifest is missing at this resource view. The output is incomplete. Preserve the original query and cursor; do not skip the missing segment or infer an empty result." },
    .{ .cause = error.InvalidResultSegment, .code = "query.invalid_result_segment", .category = .integrity, .action = .contact_operator, .message = "The result segment does not match the expected ordinal, row start, resource or publication identity. No verified continuation is available. Preserve the original query and cursor for inspection." },
    .{ .cause = error.InvalidResultDigest, .code = "query.result_digest_mismatch", .category = .integrity, .action = .contact_operator, .message = "The captured Arrow segment bytes do not match their recorded digest. No verified page can be returned. Preserve the original result reference and cursor; rerunning SQL cannot repair this historical result." },
    .{ .cause = error.InvalidResultCoverage, .code = "query.result_coverage_mismatch", .category = .integrity, .action = .contact_operator, .message = "The final segment does not establish the manifest's complete row, byte and digest-chain coverage. The emitted prefix is incomplete. Preserve the original result and cursor; do not label it complete or replace the saved query." },
    .{ .cause = error.InvalidResourceRead, .code = "query.invalid_resource_read", .category = .integrity, .action = .contact_operator, .message = "The resource response does not match the requested keys, revision, identity or snapshot. No complete authorized observation is available. Preserve the original query and report this response validation failure." },
    .{ .cause = error.InvalidAuthorityResponse, .code = "query.invalid_authority_response", .category = .integrity, .action = .contact_operator, .message = "The authority response is malformed or does not match the signed request. No trustworthy observation is available. Preserve saved work and its original identity; do not infer empty state or a terminal query result." },
    .{ .cause = error.InvalidQuerySearch, .code = "query.invalid_search", .category = .binding, .action = .correct_input, .message = "SQL suggestion search must be valid UTF-8 and at most 128 bytes. Correct the search text; this operation does not submit a query." },
    .{ .cause = error.InteractiveQueriesUnavailable, .code = "query.interactive_unavailable", .category = .unsupported, .action = .inspect_scope, .message = "The authority does not expose the leased-snapshot/read capability required by this interactive query. Inspect matching caller and authority capabilities before selecting a supported execution interface." },
    .{ .cause = error.ResourceReadBatchUnavailable, .code = "query.batch_read_unavailable", .category = .unsupported, .action = .inspect_scope, .message = "The authority does not expose the resource batch-read capability required by this query interface. Inspect matching caller and authority contracts; no unchecked metadata fallback is available." },
    .{ .cause = error.QueryClosed, .code = "query.snapshot_closed", .category = .lifecycle, .action = .inspect_status, .message = "This interactive snapshot handle is closed and cannot produce another page. Previously disclosed rows remain disclosed. Inspect any saved query separately before explicitly selecting new work." },
    .{ .cause = error.Cancelled, .code = "query.read_cancelled", .category = .lifecycle, .action = .inspect_status, .message = "The local read was interrupted by cancellation. Previously disclosed rows remain disclosed; this does not confirm cancellation or rollback of durable query work. Inspect any saved query separately." },
    .{ .cause = error.Canceled, .code = "query.attempt_cancelled", .category = .unavailable, .action = .inspect_status, .message = "This caller task was cancelled before it completed the attempt. Preserve any saved query and observed receipt; host task cancellation does not establish a durable cancellation outcome." },
    .{ .cause = error.QueryComplete, .code = "query.iteration_complete", .category = .lifecycle, .action = .inspect_status, .message = "The interactive iterator has already reached its end. It has no further page. Use its existing completion evidence; do not create another query to continue this iterator." },
    .{ .cause = error.EndOfStream, .code = "query.read_truncated", .category = .unavailable, .action = .inspect_status, .message = "Required bytes ended before this attempt completed. This cause alone does not identify whether transport or encoded data was truncated. No complete observation is available; preserve the exact saved query and cursor." },
};
pub fn fromError(cause: anyerror) ?Entry {
    for (entries) |entry| if (entry.cause == cause) return entry;
    return null;
}
